package com.chondrimaishrat.elearning.quiz;
import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Pattern; import jakarta.validation.constraints.Size;
public class QuestionForm { @NotBlank @Size(max=1000) private String questionText; @NotBlank private String optionA; @NotBlank private String optionB; @NotBlank private String optionC; @NotBlank private String optionD; @Pattern(regexp="[ABCD]") private String correctOption; public String getQuestionText(){return questionText;} public void setQuestionText(String x){questionText=x;} public String getOptionA(){return optionA;} public void setOptionA(String x){optionA=x;} public String getOptionB(){return optionB;} public void setOptionB(String x){optionB=x;} public String getOptionC(){return optionC;} public void setOptionC(String x){optionC=x;} public String getOptionD(){return optionD;} public void setOptionD(String x){optionD=x;} public String getCorrectOption(){return correctOption;} public void setCorrectOption(String x){correctOption=x;} }
